package quebec.culture.donnees;
import android.app.*;import android.content.*;import android.os.*;import android.widget.*;
public class IndigenousActivity extends Activity{@Override public void onCreate(Bundle b){super.onCreate(b);Ui.bars(this);IndigenousDatabase db=new IndigenousDatabase(this);LinearLayout r=Ui.root(this);r.addView(Ui.text(this,"Vitrine des 11 nations autochtones du Québec",27,true));r.addView(Ui.text(this,"Section distincte consacrée aux 10 Premières Nations et à la nation inuit. Les appellations évoluent; l’application présente des noms usuels et des appellations propres aux nations lorsque possible.",14,false));for(String[] x:db.nations()){LinearLayout p=Ui.panel(this);p.addView(Ui.text(this,x[0]+" — "+x[1],18,true));p.addView(Ui.text(this,x[2],14,false));Button s=Ui.secondary(this,"Rechercher cette nation dans la culture québécoise");s.setOnClickListener(v->{Intent i=new Intent(this,SearchActivity.class);i.putExtra("prefill",x[0]+" culture Québec");i.putExtra("auto_search",true);startActivity(i);});p.addView(s);r.addView(p);}LinearLayout t=Ui.panel(this);t.addView(Ui.text(this,"Repères historiques — 1534 à aujourd’hui",21,true));for(String[] x:db.history())t.addView(Ui.text(this,x[0]+" — "+x[1]+"\n"+x[2],14,false));r.addView(t);Button live=Ui.primary(this,"Explorer les données publiques culturelles");live.setOnClickListener(v->startActivity(new Intent(this,LiveDataActivity.class)));r.addView(live);setContentView(Ui.wrap(this,r));}}
